programs.haiku:
"""Layer 15 MLP hidden unit 130 (down_proj component 130), as a readable rule set.

What the component does: its activation is the MLP hidden unit's value, silu(gate) * up,
scaled into the residual stream. Its value is context-driven and diffuse, so only a few
concepts carry a little of it:

- Negative, the largest values: a linking verb (is, was, are, were) inside a relative
  clause, shortly after "which", "whom", "whose" or "where", as in "... of which the
  deceased was ...". These reach -20 or more.
- Negative, milder: unit and time nouns (minutes, hours, km, feet, weeks ...), case
  particles (が, を, に, 이, 을 ...), and the linking verbs elsewhere.
- Positive: the closing parenthesis of a distance given in miles or km, as in
  "(7 mi)", which is the strongest positive pattern.
- Everything else, including code and most prose, predicts about zero.

The values are least-squares fits on training text. They explain about 0.2% of the
variance, so this is a rough description of where the component's mass sits, not an
accurate predictor.
"""

READS = ()

LINKING = {"is", "was", "are", "were"}
RELATIVE = {"which", "whom", "whose", "where"}
DISTANCE = {"mi", "km"}
UNITS = {
    "kilometres", "km", "mi", "million", "billion", "minutes", "hours", "seconds", "feet",
    "inches", "mm", "cm", "times", "characters", "weeks", "days", "months", "years",
}
CASE_PARTICLES = {"が", "を", "に", "は", "の", "で", "と", "も", "로", "으로", "가", "이", "을", "를", "에", "의", "은", "는", "에서"}
NEGATIONS = {"not", "no", "never"}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    words = [_word(s) for s in prefix.token_strings[-7:]]
    now, before = words[-1], words[:-1]
    if now in LINKING and any(w in RELATIVE for w in before):
        return carry, -0.54
    if now == ")" and any(w in DISTANCE for w in before):
        return carry, 2.9
    if now in LINKING:
        return carry, -0.07
    if now in UNITS:
        return carry, -0.23
    if now in CASE_PARTICLES:
        return carry, -0.1
    if now in NEGATIONS:
        return carry, 0.21
    return carry, 0.0

"""Layer 15 MLP hidden unit 136 (read out by down_proj component 136).

What it does, in plain terms: the component goes negative when the text copies a passage
that already occurred earlier in the same document. The longer the copied run, the more
negative, and about three times as much when the copy says a digit comes next.

On top of that, some token types have fixed offsets:
- a space right after another space (indentation, padding): strongly negative;
- " of" and negation stems ("don", "didn", "isn", ...): negative;
- code punctuation (\\ _ ^): negative;
- the digits 1 and 2: strongly negative when they start a number (after a space), mildly
  negative inside running text, and less negative when the digit follows another digit.

The program keeps, per document, the place of every run of up to MAX_RUN tokens. At each
position it finds the longest run ending here that occurred before (its length is the copy
length) and the token that followed that earlier occurrence (the copy's guess for the next
token).
"""

READS = ()

MAX_RUN = 6
COPY_SLOPE = -0.17  # per token of copied run
COPY_DIGIT_FACTOR = 3  # multiplier when the copy's guess is a digit
WHITESPACE_RUN = -3.1
NUMBER_START = -2.2  # digit 1 or 2 right after a space
DIGIT_IN_TEXT = -0.7  # digit 1 or 2 elsewhere
AFTER_DIGIT = 0.6  # any token right after a digit
OFFSET = {" of": -2.15, "\\": -2.2, "_": -2.2, "^": -2.2}
NEGATION_STEMS = {"don", "doesn", "didn", "isn", "wasn", "aren", "weren", "couldn",
                  "wouldn", "shouldn", "haven", "hasn", "hadn"}


def _offset(tok, prev):
    if tok.strip() == "" and tok and prev.strip() == "" and prev:
        return WHITESPACE_RUN
    if tok in ("1", "2"):
        return NUMBER_START if prev.isspace() else DIGIT_IN_TEXT
    if tok in OFFSET:
        return OFFSET[tok]
    if tok.strip().lower() in NEGATION_STEMS:
        return -2.4
    return 0.0


def step(carry, prefix, upstream):
    ids = prefix.token_ids
    t = len(ids) - 1
    doc = prefix.document_ids[t]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "start": t, "last": [dict() for _ in range(MAX_RUN + 1)]}
    start, last = carry["start"], carry["last"]

    copy_len, guess = 0, None
    for k in range(1, MAX_RUN + 1):
        if t - k + 1 < start:
            break
        key = tuple(ids[t - k + 1:t + 1])
        if key not in last[k]:
            break
        copy_len, guess = k, last[k][key] + 1
    for k in range(1, MAX_RUN + 1):
        if t - k + 1 < start:
            break
        last[k][tuple(ids[t - k + 1:t + 1])] = t

    prev = prefix.token_strings[t - 1] if t > start else ""
    digit_next = guess is not None and prefix.token_strings[guess].strip().isdigit()
    value = _offset(prefix.token_strings[t], prev)
    value += AFTER_DIGIT * (prev.strip().isdigit() and prev != "")
    value += COPY_SLOPE * copy_len * (COPY_DIGIT_FACTOR if digit_next else 1)
    return carry, float(value)

"""Serial-list conjunctions: a negative response on 'and' / 'or' / 'nor' that closes a
list, i.e. comes right after a comma. The more list commas already seen in the same
sentence, the more negative it is. Everything else predicts 0."""

READS = ()

CONJUNCTIONS = {"and", "or", "nor"}
SENTENCE_BREAKS = {".", "!", "?", ";", ":"}


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    word = tokens[-1].strip()
    if word not in CONJUNCTIONS or len(tokens) < 2:
        return carry, 0.0
    if tokens[-2].strip() != "," or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    # count the commas earlier in this sentence
    commas = 0
    for i in range(len(tokens) - 2, -1, -1):
        if prefix.document_ids[i] != prefix.document_ids[-1]:
            break
        piece = tokens[i].strip()
        if piece in SENTENCE_BREAKS or "\n" in tokens[i]:
            break
        if piece == ",":
            commas += 1
    return carry, (-0.8 if commas == 0 else -1.8)

"""Component layers.15.mlp.down_proj:154: a clause-opener detector.

What it responds to, in plain terms:
- Words that open an embedded clause or question: complementizers and wh-words such as
  "that", "how", "whether", "if", "when", "where", "which", "what", "why", and their
  counterparts in other languages ("que", "что", "когда", "dass", "wenn", "cómo", ...).
  They fire most after a verb ("shows that", "see how", "check if", "ensure that") or a
  preposition ("in which", "at which"). They are weaker (about a third) for a relative
  "which"/"that" after a comma, and zero for the demonstrative "that" in "in that".
- Verbs that take a clause or infinitive complement: "allows", "enable", "ensure", "help",
  "prevent".
- The word right after a clause opener ("when the", "how much").
- The comma that closes a sentence-opening phrase ("In this case,", "As a result,",
  "If ..., ") -- the first comma of a sentence that starts with one of those words.

Everything else predicts 0. The rules are a rough summary: they explain about 8-9% of the
variance (r about 0.3), since most of the activation is spread over contexts they do not capture.
"""
from wordnet import parts_of_speech, base_forms

READS = ()

# clause openers, with the typical size of their activation
OPENER = {
    " that": 1.4, " how": 4.0, " whether": 5.0, " where": 2.5, " when": 2.0, " why": 3.0,
    " what": 1.7, " if": 1.3, " which": 1.0, " while": 1.0, " whenever": 3.0, " unless": 1.9,
    " que": 1.5, " что": 2.4, " когда": 4.9, " как": 1.9, " dass": 2.9, " wenn": 2.1,
    " cómo": 3.7, " если": 2.0, " che": 1.4, " где": 3.7, " чтобы": 2.1,
}
# verbs that take a clause or infinitive complement
ENABLE = {
    " allows": 3.5, " allow": 3.1, " allowing": 3.0, " enable": 2.4, " enables": 3.0,
    " ensure": 2.2, " help": 1.6, " helps": 2.0, " prevent": 1.7, " sure": 1.6,
}
# the comma closing an introductory phrase, by the word that opened the sentence
INTRO = {
    "In": 2.4, "As": 2.2, "To": 2.2, "When": 1.8, "For": 1.3, "If": 1.1,
    "However": 1.0, "Therefore": 1.2, "But": 0.8, "So": 0.7,
}
PREPOSITIONS = {" in", " on", " at", " by", " through", " with", " of", " about", " from", " to", " for"}


def is_verb(token):
    """Whether the word is a verb (or the base form of one), by WordNet."""
    word = token.strip().lower()
    if not word:
        return False
    return any("verb" in parts_of_speech(form) for form in (base_forms(word) or (word,)))


def step(carry, prefix, upstream):
    # carry: (first word of the current sentence, commas seen in it so far)
    first, n_commas = carry if carry is not None else (None, 0)
    token = prefix.token_strings[-1]
    before = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    value = 0.0
    if token in OPENER:
        value = OPENER[token]
        if before == ",":
            value *= 0.3
        elif before in PREPOSITIONS:
            if token == " that":
                value = 0.0
            elif token == " which":
                value *= 2.0
        elif is_verb(before):
            value *= 1.5
    elif token in ENABLE:
        value = ENABLE[token]
    elif token in (" much", " many") and before == " how":
        value = 5.0
    elif token in (" the", " a", " an") and before in OPENER:
        value = 1.0
    elif token == ",":
        value = INTRO.get(first, 0.0) if n_commas == 0 else 0.3
        n_commas += 1
    if first is None and token.strip():
        first = token.strip()
    if any(c in token for c in ".!?\n"):
        first, n_commas = None, 0
    return (first, n_commas), value

"""Layer 15 MLP down-projection, component 155: a "condition and comparison" detector.

It responds to text that states a condition or a comparison:
- an equality or inequality operator (==, !=, <=, >=, <, >) fires, most for == and !=;
- "than" right after a comparative ("less than", "greater than", "higher than") fires;
- relation words (exceeds, divides, at least, multiple of) fire a little less;
- the words just after an opener ("if", "whether", "once", "elif", or the same in
  other languages) fire: most in the first three tokens of the clause, less up to six,
  and "you" / "you are" inside an "if you ..." clause fire the most, until the sentence ends.
Everything else sits near a small negative baseline. The rule explains only a little of
the variance: the component is diffuse, with many large values no word list captures.
"""

OPENERS = {"if", "elif", "whether", "unless", "once", "when", "如果", "若", "если", "wenn", "si", "nếu", "もし"}
COMPARATORS = {"less", "greater", "more", "higher", "larger", "smaller", "lower", "longer",
               "bigger", "shorter", "fewer", "above", "below", "older", "younger", "better"}
EQUALITY = {"==", "===", "!=", "!==", "≠"}
COMPARE = {"<=", ">=", "≤", "≥", "<", ">"}
RELATION_WORDS = {"exceeds", "exceed", "divides", "divisible", "least", "multiple"}
YOU_WORDS = {"are", "want", "have", "need", "'re", "’re"}
SENTENCE_END = {".", "?", "!", ";"}

READS = ()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip().lower()
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "pos": -1, "opener": None, "end": None, "prev": ""}
    carry["pos"] += 1
    p = carry["pos"]
    if "\n" in tok or tok in SENTENCE_END:
        carry["end"] = p
    if tok in OPENERS:
        carry["opener"] = p
    prev = carry["prev"]
    carry["prev"] = tok
    in_clause = carry["opener"] is not None and (carry["end"] is None or carry["end"] < carry["opener"])
    d = p - carry["opener"] if in_clause else 0

    value = -0.04
    if tok in EQUALITY:
        value = 1.5
    elif tok in COMPARE:
        value = 0.4
    elif tok == "than" and prev in COMPARATORS:
        value = 1.0
    elif tok in RELATION_WORDS:
        value = 0.5
    elif in_clause and tok == "you" and d == 1:
        value = 1.5
    elif in_clause and prev == "you" and tok in YOU_WORDS:
        value = 1.2
    elif in_clause and 1 <= d <= 3:
        value = 0.7
    elif in_clause and 4 <= d <= 6:
        value = 0.3
    return carry, value

"""Layer 15, MLP hidden unit 156. The component is dominated by that unit: it carries about half
of the component's covariance with its activation, and the other hidden units are each under 1%.

The unit is diffuse: no word or syntax cue explains most of its variance (a lookup by current
token reaches under 5% on held-out text). These cues move it the most, so the program predicts
them and leaves every other token at about zero:

- augmented assignment operators (+=, -=, *=, /=): strongly negative;
- verbs that insert, replace or multiply content (replace, insert, append, put, fill, ...): positive;
- "affected by" passive words (affected, damaged, filled, replaced, ...) and the by / with / 被 /
  durch that follow them: mildly negative;
- a comma inside an open bracket, i.e. between arguments of a call or signature: mildly negative.

Bracket depth is carried from token to token and reset at each document start.
"""

READS = ()

AUG_OPS = {"+=", "-=", "*=", "/="}
INSERT_VERBS = {
    "replace", "replacing", "insert", "append", "put", "fill", "filling",
    "multiply", "multiplying", "push",
}
AFFECTED = {
    "affected", "influenced", "damaged", "updated", "filled", "replaced", "amended",
    "edited", "covered", "struck", "by", "with", "受到", "被", "durch",
}
OPEN, CLOSE = "([{", ")]}"


def step(carry, prefix, upstream):
    depth = carry or 0
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        depth = 0
    tok = prefix.token_strings[-1]
    word = tok.strip().lstrip(".").lower()
    if tok.strip() in AUG_OPS:
        value = -3.4
    elif word in INSERT_VERBS:
        value = 0.8
    elif word in AFFECTED:
        value = -0.4
    elif tok.startswith(",") and depth > 0:
        value = -0.33
    else:
        value = 0.0
    depth = max(0, depth + sum(c in OPEN for c in tok) - sum(c in CLOSE for c in tok))
    return depth, value

"""Layer 15 MLP down_proj, component 157: a coordination detector.

Plain version: the component is switched on by the word that joins two parallel items,
i.e. the conjunction "or" (strongest) and "and", and the same conjunction in other
languages ("und", "et", "и", "или", "y", "و"). The value is higher when the
conjunction follows a word (as in "strength and", "one or") than when it follows
punctuation. "to" between numbers or months ("from June to October", "20% to 60%") also
switches it on, as a range joiner. Everywhere else the component stays near zero.
"""

READS = ()

# Typical activation on each conjunction, after a word and after punctuation or a number.
CONJUNCTION = {" or": (2.3, 1.3), " and": (1.0, 0.3), " und": (0.9, 0.5), " et": (0.4, 0.3),
               " y": (0.3, 0.2), " и": (1.0, 0.5), " или": (1.8, 1.0), " e": (0.3, 0.2),
               " و": (0.8, 0.4), " AND": (0.9, 0.5)}
MONTHS_AND_NUMBER_WORDS = {"one", "two", "three", "four", "five", "ten", "hundred", "june",
                           "july", "august", "september", "october", "november", "december",
                           "january", "february", "march", "april", "may"}
RANGE_VALUE = 1.0


def _is_word(token):
    return token.strip().isalpha()


def _is_number(token):
    return token.strip().isdigit()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    before = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if token in CONJUNCTION:
        after_word, after_other = CONJUNCTION[token]
        return carry, after_word if _is_word(before) else after_other
    if token == " to" and (_is_number(before) or before.strip().lower() in MONTHS_AND_NUMBER_WORDS):
        return carry, RANGE_VALUE
    return carry, 0.0

"""Explain-by-rule for layers.15.mlp.down_proj:159: the "of" detector.

This component switches on for the word "of" (and its Romance cousin "de"),
the preposition that links a noun to what it is a part, amount or kind of:
"some of them", "portion of the", "the number of", "one of the".
Its activation is large on " of" and close to zero on almost every other
token. The size of the "of" response depends on the word before it:

- quantity or part words ("some of", "most of", "portion of", "% of"):
  strongest, about 6;
- fixed or verb/adjective-governed phrases ("out of", "instead of",
  "because of", "instance of", "sort of"): weak, about 1.5;
- any other noun before "of": about 4.
Other "of"-words: " de" about 1.8, " di" about 1.3. Every other token sits at
about -0.1, the average of the rest.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

PARTITIVE = {
    "some", "any", "many", "all", "each", "most", "one", "half", "rest",
    "portion", "part", "piece", "group", "none", "majority", "percent", "%",
    "lot", "amount", "range", "number", "set", "sum",
}
FIXED = {
    "out", "instead", "because", "instance", "place", "sort", "kind", "way",
    "use", "member", "case", "regardless", "terms", "full", "think", "sense",
}
OTHER_OF = {" de": 1.8, " di": 1.3}


def step(carry, prefix, upstream: Mapping):
    token = prefix.token_strings[-1]
    if token.strip().lower() == "of":
        same_doc = prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
        before = prefix.token_strings[-2].strip().lower() if same_doc else ""
        if before in PARTITIVE:
            value = 6.0
        elif before in FIXED:
            value = 1.5
        else:
            value = 4.0
    else:
        value = OTHER_OF.get(token, -0.1)
    return carry, float(value)

"""Coordination detector: a connective that joins two parallel items.

Unit 160 of layer 15's MLP output is switched on at a word that joins two parallel
items: "and", "or", their translations ("und", "et", "y", "и", "和", "或", ...), and
the "to" or dash of a range after a number ("2002 to 2010", "10-20").

How strongly it fires depends on the word just before the connective, read by its
part of speech (WordNet, with word endings for words it does not list):
  - an adjective or adverb ("new and improved", "simple or easy"): strong, and
    stronger still after a copula ("is fun and", "were clear or");
  - a verb ("find and fix"): moderate;
  - a noun ("organ and vascular", "files and"): weak.
A comma or dash in a list of adjectives ("fresh, clean, ...") gets a small positive
value; after a noun it is about zero. Every other token is predicted at 0.
"""

import wordnet

READS = ()

COPULA = {"is", "are", "was", "were", "be", "been", "being", "very", "so", "too", "really", "quite"}
OTHER_CONJUNCTIONS = {
    "&", "und", "et", "y", "e", "ou", "oder", "og", "och", "ve", "eller", "nor",
    "и", "или", "і", "و", "أو", "và", "和", "或", "与", "及", "且",
}
COMMA = {",", "，", "、", "-", "–", "/"}
ADJECTIVE_ENDINGS = (
    "ous", "ive", "ful", "ic", "able", "ible", "ly", "ed", "ing", "less", "ish", "al",
)
NOUN_ENDINGS = ("tion", "ment", "ness", "ity", "ance", "ence", "ism", "ist", "er", "or")

# Mean activation by the class of the word before the connective:
# (adjective or adverb, verb, noun, anything else).
AND_VALUES = (9.0, 4.0, 3.1, 1.8)
OR_VALUES = (9.5, 5.6, 4.2, 3.0)
COMMA_VALUES = (1.2, 0.3, 0.2, 0.5)
OTHER_VALUE = 2.0


def word_class(word):
    """0 adjective or adverb, 1 verb, 2 noun, 3 anything else."""
    if not word or not word.isascii() or not word.isalpha():
        return 3
    poses = wordnet.parts_of_speech(word.lower()) or ()
    if "adjective" in poses or "adverb" in poses:
        return 0
    if "verb" in poses:
        return 1
    if "noun" in poses:
        return 2
    # Not in WordNet (rare words, word fragments): guess from the ending.
    if word.endswith(ADJECTIVE_ENDINGS):
        return 0
    if word.endswith(NOUN_ENDINGS):
        return 2
    return 3


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip().lower()
    prev, before = "", ""
    n = len(prefix.token_ids)
    if n > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip()
        if n > 2 and prefix.document_ids[-3] == prefix.document_ids[-1]:
            before = prefix.token_strings[-3].strip().lower()
    if prev[-1:].isdigit() and tok in ("to", "-", "–"):
        return carry, 2.5  # a numeric range: "2002 to 2010"
    if tok == "and" and prev[-1:].isdigit():
        return carry, 2.7
    if tok in ("and", "or"):
        cls = word_class(prev)
        if cls == 0 and before in COPULA:
            return carry, 12.0  # predicate adjective: "is fun and"
        return carry, (AND_VALUES if tok == "and" else OR_VALUES)[cls]
    if tok in OTHER_CONJUNCTIONS:
        return carry, OTHER_VALUE
    if tok in COMMA:
        return carry, COMMA_VALUES[word_class(prev)]
    return carry, 0.0

"""Abbreviation-introducing parenthesis detector (mostly negative).

The component goes negative on an opening parenthesis that follows a named or
technical term, where the model expects an abbreviation or acronym next:
"European Bank for Reconstruction and Development (EBRD)", "Focus Group
Discussions (FGDs)". The more capitalized words in the run just before the "(",
and the rarer those words, the more negative it is. A "(" after math, code,
numbers or punctuation stays near zero. Some openers that lead into a
definition, conclusion or list ("So", "Thus", "Therefore", "i.e", a colon before
a line break) are mildly negative. Everything else is predicted as 0.
"""

import re

from wordfreq import zipf_frequency

READS = ()

PAREN = {" (", "（"}
OPENERS = {"So": -1.5, " So": -1.0, "Thus": -1.4, "Therefore": -1.1, ":\n\n": -0.8, ".e": -2.3}


def paren_value(prefix):
    """Value at an opening parenthesis, from the words before it in the same document."""
    doc = prefix.document_ids[-1]
    words = []
    for i in range(len(prefix.token_strings) - 2, -1, -1):
        if prefix.document_ids[i] != doc or "\n" in prefix.token_strings[i] or len(words) >= 6:
            break
        words.insert(0, prefix.token_strings[i])
    found = re.findall(r"[A-Za-z][A-Za-z\-]*", "".join(words))
    if not found:
        return -0.9
    run = 0  # capitalized words (or "of", "and", "for", "the") ending right before the "("
    for w in reversed(found):
        if w[0].isupper() or w.lower() in ("of", "and", "for", "the"):
            run += 1
        else:
            break
    if run >= 3:
        return -3.5
    rare = min(zipf_frequency(w.lower(), "en") for w in found[-3:]) < 4
    return -1.5 if rare else -0.6


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in PAREN:
        return carry, paren_value(prefix)
    return carry, OPENERS.get(tok, 0.0)

"""Draft v3: effort/advice register (negative), factual dates and CJK punctuation (positive)."""
READS = ()
ADVICE = frozenset("ask try learn practice use using follow remember focus seek treat think thinking approach asking asked always often usually carefully thoroughly consistently constantly never sometimes how like commitment dedication effort standards strategy process steps skills".split())
STRIVE = frozenset("commitment committed dedication dedicated strive striving effort willingness eager learn try how ask approach steps best desire afraid".split())
MONTHS = frozenset("january february march april may june july august september october november december".split())
CJK_PUNCT = frozenset("，、的。：")

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = ""
    if len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if word == "to" and prev in STRIVE:
        return carry, -1.0
    if word in ADVICE:
        return carry, -0.35
    if word in MONTHS:
        return carry, 0.12
    if word in CJK_PUNCT:
        return carry, 0.1
    return carry, 0.0

"""L15 MLP down_proj component 189: a separator and path-opener detector.

Plain-terms summary. This component is positive on the punctuation that
introduces a value in "Label: value" text and in key/value, path and
attribute strings:
  - colons (":", " :", "：", ":\\n", '":'), strongest after a word such as
    "occupation:" or "directory:", weaker after a number (times, ratios);
  - the opening of a quoted or relative path or URL (' "/', " '/", ' `/',
    '("/', ' ./', ':///'), the strongest positive tokens;
  - arrows and dashes used as separators ("->", "—", "|");
  - escaped quotes that open an attribute value (' \\"', '=\\"').
It is negative on a few code identifiers that name keys or operators
("name", "type", "given", "id", "==", "::"). Almost every other token is
about zero, and most of the variance is context-specific noise that no
short rule captures.

The program looks at the newest token and the one before it (within the
same document) and predicts one value per token from these classes.
"""

import re

READS = ()

COLON = re.compile(r"\s?[:：]\n?|\":")
NUMBER = re.compile(r"[0-9]+")
WORD = re.compile(r"[A-Za-z]+")
ARROWS = {"->", "=>", "→", "—", "|", "–"}
PATH_OPENER = re.compile(r"""\s?["'`(=]+\.?/\S*|\s?\./\S*|:///""")
PATH = re.compile(r"\s?\.?/\S*|\s?\(/|://\S*")
ESCAPED_QUOTE = re.compile(r'\\"')
KEY_WORDS = {"name", "type", "given", "id"}
OPERATORS = {"==", "===", "::", ".createElement"}


def value_of(tok, prev):
    """The predicted activation for token `tok` after the token `prev`."""
    s = tok.strip()
    if COLON.fullmatch(tok):
        if NUMBER.fullmatch(prev.strip()):
            return 1.4  # a colon after a number, as in times and ratios
        if WORD.fullmatch(prev.strip()):
            return 2.4  # a colon after a word, as in "occupation:"
        return 2.7
    if PATH_OPENER.fullmatch(tok):
        return 6.0  # a quoted or relative path or URL starts here
    if s in ARROWS:
        return 1.1
    if PATH.fullmatch(tok):
        return 0.3
    if ESCAPED_QUOTE.search(tok) or s == '"$':
        return 1.5
    if s in KEY_WORDS:
        return -1.1
    if s in OPERATORS:
        return -0.8
    return 0.0


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    return carry, float(value_of(tok, prev))
